import hashlib
import hmac
import json
import base64
import time
import os
from http.server import HTTPServer, BaseHTTPRequestHandler
import urllib.parse

SECRET_KEY = os.environ.get('SECRET_KEY', 'super-secret-key-do-not-share').encode()
ADMIN_USERS = {'admin', 'root', 'superuser'}

def b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

def b64url_decode(s: str) -> bytes:
    padding = 4 - len(s) % 4
    if padding != 4:
        s += '=' * padding
    return base64.urlsafe_b64decode(s)

def create_token(username: str, role: str, expires_in: int = 3600) -> str:
    header = {'alg': 'HS256', 'typ': 'JWT'}
    payload = {
        'sub': username,
        'role': role,
        'iat': int(time.time()),
        'exp': int(time.time()) + expires_in
    }
    h = b64url_encode(json.dumps(header, separators=(',', ':')).encode())
    p = b64url_encode(json.dumps(payload, separators=(',', ':')).encode())
    signing_input = f'{h}.{p}'.encode()
    signature = hmac.new(SECRET_KEY, signing_input, hashlib.sha256).digest()
    return f'{h}.{p}.{b64url_encode(signature)}'

def verify_token(token: str) -> dict:
    """Verify token signature and expiration. Returns payload if valid."""
    parts = token.split('.')
    if len(parts) != 3:
        raise ValueError('Invalid token format')

    header_b64, payload_b64, sig_b64 = parts

    # Decode and validate header
    header = json.loads(b64url_decode(header_b64))
    if header.get('alg') != 'HS256':
        raise ValueError('Unsupported algorithm')

    # Verify signature
    signing_input = f'{header_b64}.{payload_b64}'.encode()
    expected_sig = hmac.new(SECRET_KEY, signing_input, hashlib.sha256).digest()
    provided_sig = b64url_decode(sig_b64)

    if not hmac.compare_digest(expected_sig, provided_sig):
        raise ValueError('Invalid signature')

    # Decode payload
    payload = json.loads(b64url_decode(payload_b64))

    # Check expiration
    if 'exp' in payload:
        if time.time() > payload['exp']:
            raise ValueError('Token expired')

    return payload

def check_permission(payload: dict, required_role: str) -> bool:
    """Check if the token payload grants the required role.

    Role hierarchy: admin > moderator > user > guest
    Higher roles inherit permissions of lower roles.
    """
    role_levels = {'guest': 0, 'user': 1, 'moderator': 2, 'admin': 3}

    user_role = payload.get('role', 'guest')
    user_level = role_levels.get(user_role, 0)
    required_level = role_levels.get(required_role, 0)

    # Grant access if user's level meets or exceeds required level
    return user_level >= required_level

def sanitize_username(username: str) -> str:
    """Sanitize username to prevent injection attacks."""
    allowed = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-.')
    return ''.join(c for c in username if c in allowed)[:64]

class TokenRequestHandler(BaseHTTPRequestHandler):

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        path = parsed.path
        params = urllib.parse.parse_qs(parsed.query)

        if path == '/api/profile':
            self.handle_profile(params)
        elif path == '/api/admin/users':
            self.handle_admin_users(params)
        elif path == '/api/login':
            self.handle_login(params)
        else:
            self.send_error(404)

    def handle_login(self, params):
        username = params.get('username', [''])[0]
        password = params.get('password', [''])[0]

        username = sanitize_username(username)
        if not username:
            self.send_json(400, {'error': 'Invalid username'})
            return

        # Simplified auth - in production would check password hash
        if not password or len(password) < 8:
            self.send_json(401, {'error': 'Invalid credentials'})
            return

        role = 'admin' if username in ADMIN_USERS else 'user'
        token = create_token(username, role)
        self.send_json(200, {'token': token, 'username': username, 'role': role})

    def handle_profile(self, params):
        token = params.get('token', [''])[0]
        if not token:
            self.send_json(401, {'error': 'Token required'})
            return

        try:
            payload = verify_token(token)
        except ValueError as e:
            self.send_json(401, {'error': str(e)})
            return

        self.send_json(200, {
            'username': payload.get('sub'),
            'role': payload.get('role'),
            'expires': payload.get('exp')
        })

    def handle_admin_users(self, params):
        token = params.get('token', [''])[0]
        target_user = params.get('target', [''])[0]
        new_role = params.get('new_role', [''])[0]

        if not token:
            self.send_json(401, {'error': 'Token required'})
            return

        try:
            payload = verify_token(token)
        except ValueError as e:
            self.send_json(401, {'error': str(e)})
            return

        # Check admin permission
        if not check_permission(payload, 'admin'):
            self.send_json(403, {'error': 'Admin access required'})
            return

        # Additional check: verify the subject is in admin list
        subject = payload.get('sub', '')
        if subject not in ADMIN_USERS:
            self.send_json(403, {'error': 'Not an authorized admin'})
            return

        if target_user and new_role:
            target_user = sanitize_username(target_user)
            if new_role not in ('guest', 'user', 'moderator', 'admin'):
                self.send_json(400, {'error': 'Invalid role'})
                return
            self.send_json(200, {'action': 'role_updated', 'target': target_user, 'new_role': new_role})
        else:
            self.send_json(200, {'users': list(ADMIN_USERS)})

    def send_json(self, status, data):
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())


def run_server(port=8080):
    server = HTTPServer(('127.0.0.1', port), TokenRequestHandler)
    print(f'Server running on port {port}')
    server.serve_forever()

if __name__ == '__main__':
    run_server()
